/* Source-backed explanation. No training, serving or robot control is executed by this page. */
function engineSource(id,label){const s=MODEL_ENGINE_CORE.sources.find(x=>x.id===id);return `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(label||s.title)} ↗</a>`;}
function engineTitle(n,title,description){return `<header class="engine-section-title"><span>${n}</span><div><h2>${title}</h2><p>${description}</p></div></header>`;}
function enginePolicyFigure(){return `<figure class="engine-paper-figure"><header><div><span class="engine-paper-label">HÌNH TÁC GIẢ · GR00T N1.5</span><h3>Kiến trúc policy nền</h3></div></header><a class="engine-paper-image" href="https://research.nvidia.com/labs/gear/n1_5/architecture.svg" target="_blank" rel="noopener"><img src="https://research.nvidia.com/labs/gear/n1_5/architecture.svg" alt="Architecture diagram GR00T N1.5 do NVIDIA công bố" loading="lazy"></a><figcaption><p>Hình gốc NVIDIA, 11/06/2025. VLM tạo features; DiT xử lý state và noisy actions. Đây là official recipe; human wrist và FOCA candidate của A1 được trình bày riêng bên dưới.</p><div><span>Ảnh tải từ nguồn tác giả · cần internet</span><a href="https://research.nvidia.com/labs/gear/gr00t-n1_5/" target="_blank" rel="noopener">Nguồn và giải thích architecture ↗</a></div></figcaption></figure>`;}
function enginePaperFigure(id,priority=false){const m=MEDIA[id],p=m.provenance,asset=m.url.split('/').pop(),credit=`Li và cộng sự (2026) · Figure ${p.figure}, trang ${p.page} · arXiv:2609.17210v1`;return `<figure class="engine-paper-figure" data-asset="${esc(asset)}" data-source-asset="${esc(asset)}" data-caption="${esc(credit)}"><header><div><span class="engine-paper-label">HÌNH GỐC · FIGURE ${p.figure}</span><h3>${esc(m.title)}</h3></div><button type="button" data-engine-figure aria-label="Phóng to Figure ${p.figure}">Phóng to ↗</button></header><a class="engine-paper-image" href="${esc(m.url)}" target="_blank" rel="noopener" aria-label="Mở ảnh gốc Figure ${p.figure}"><img src="${esc(m.url)}" alt="${esc(m.title)} — ${esc(m.caption)}" loading="${priority?'eager':'lazy'}" ${priority?'fetchpriority="high"':''} width="3060" height="${Math.round((p.cropPoints[3]-p.cropPoints[1])*p.renderScale)}"></a><figcaption><p>${esc(m.caption)}</p><div><span>${esc(credit)}</span><a href="${esc(m.source)}" target="_blank" rel="noopener">Paper gốc ↗</a><a href="${esc(m.license.url)}" target="_blank" rel="noopener">${esc(m.license.label)}</a></div></figcaption></figure>`;}
function engineModuleView(x){return `<div class="engine-module-heading"><div><small>${esc(x.tag)}</small><h3>${esc(x.title)}</h3></div><span class="engine-badge">Khảo sát upstream</span></div>${x.figure?enginePaperFigure(x.figure):''}<div class="engine-contract"><article><small>INPUT</small><p>${esc(x.input)}</p></article><article><small>XỬ LÝ</small><p>${esc(x.process)}</p></article><article><small>OUTPUT</small><p>${esc(x.output)}</p></article></div><div class="engine-contract-note"><strong>Mapping vào idea</strong><p>${esc(x.boundary)}</p></div><details class="engine-details"><summary>Đối chiếu với file trong FluxVLA</summary><p><a href="https://github.com/FluxVLA/FluxVLA/blob/main/${esc(x.path)}${x.anchor?'#'+esc(x.anchor):''}" target="_blank" rel="noopener"><code>${esc(x.path)}</code> ↗</a></p><p class="engine-note">File trên nhánh main có thể thay đổi; phải pin commit và dependencies trước khi chạy native.</p></details>`;}
function engineLifecycleView(x){return `<h3>${esc(x.title)}</h3>${x.figure?enginePaperFigure(x.figure):''}<ol class="engine-lifecycle-flow">${x.steps.map(([t,b],i)=>`<li><span>0${i+1}</span><strong>${esc(t)}</strong><p>${esc(b)}</p></li>`).join('')}</ol><div class="engine-lifecycle-detail"><p>${esc(x.detail)}</p><div><small>ARTIFACTS CHO DATA FLYWHEEL</small><p>${esc(x.handoff)}</p></div></div><p class="engine-note">${engineSource(x.source)} · Workflow A1 là thiết kế; chưa native run.</p>`;}
function renderModelEngineCore(){const d=MODEL_ENGINE_CORE;return `<div id="model-engine-core" class="engine-page">
 <section class="engine-hero"><div class="engine-hero-copy"><span class="engine-kicker">MODEL ENGINE CORE · FLUXVLA</span><h1>Một engine.<br>Từ học đến robot thật.</h1></div><div class="engine-hero-intro"><p>Chọn FluxVLA vì nó nối <strong>training → evaluation → inference trên robot thật</strong>.</p><p>Model AI là policy bên trong. Data Core quyết định dữ liệu cho vòng học tiếp theo.</p><div class="engine-hero-links"><button type="button" data-engine-jump="engine-lifecycle">Khám phá toàn luồng ↓</button>${engineSource('report','Đọc technical report')}</div></div></section>
 ${engineeringScope()}
 ${enginePaperFigure('fluxFramework',true)}
 <div class="engine-identity"><article><small>ENGINE / FRAMEWORK</small><strong>FluxVLA</strong><p>Data pipelines, runners, artifacts và runtime</p></article><article><small>POLICY ĐỀ XUẤT CHO MVP</small><strong>GR00T N1.5</strong><p>Eagle VLM + DiT Action Expert</p></article><article><small>MÔI TRƯỜNG / THIẾT BỊ</small><strong>Sim → robot đích</strong><p>Evaluator và operator theo embodiment</p></article></div>
 <section class="engine-section" id="engine-lifecycle">${engineTitle('01','Training → eval → robot thật','Chọn một giai đoạn để thấy dữ liệu đi qua đâu và artifact nào quay về flywheel.')}<div class="engine-tabs" role="group" aria-label="Giai đoạn của Model Engine Core">${d.lifecycle.map((x,i)=>`<button type="button" data-engine-life="${esc(x.id)}" aria-pressed="${i===0}" aria-controls="engine-life-view">${esc(x.label)}</button>`).join('')}</div><div id="engine-life-view" class="engine-life-view" aria-live="polite">${engineLifecycleView(d.lifecycle[0])}</div></section>
 <section class="engine-section">${engineTitle('02','FluxVLA gồm những thành phần nào?','Config chọn implementations qua registry; các modules phải giữ đúng data/action contracts.')}<div class="engine-module-tabs" role="group" aria-label="Thành phần FluxVLA">${d.modules.map((x,i)=>`<button type="button" data-engine-module="${esc(x.id)}" aria-pressed="${i===0}" aria-controls="engine-module-view"><span>0${i+1}</span><strong>${esc(x.label)}</strong><small>${esc(x.tag)}</small></button>`).join('')}</div><div id="engine-module-view" class="engine-module-view" aria-live="polite">${engineModuleView(d.modules[0])}</div></section>
 <section class="engine-section">${engineTitle('03','Policy nào thực sự được học?','MVP kế thừa pretrained GR00T N1.5; human và action-free video là candidates mở rộng có đối chứng.')} ${enginePolicyFigure()}${renderModelAI()}${nativeRunCard()}<details class="engine-details engine-config"><summary>Đọc kỹ recipe FluxVLA đang chọn: model, tensor dimensions và training config</summary><div class="engine-config-grid">${d.configFacts.map(([a,b,c])=>`<article><small>${esc(a)}</small><strong>${esc(b)}</strong><p>${esc(c)}</p></article>`).join('')}</div><p class="engine-note"><strong>Thông số của recipe public, không là config A1 đã chạy.</strong> 29D active action là hai arms + hai hands + waist; padding 32D/state64D không phải số joints robot đích. Profile một tay/torso cố định phải khai bridge, action masks và binding riêng. N1.5 official giữ VLM frozen; Flux recipe này mở visual. 30.000 steps không phải cam kết ngân sách few-shot.</p><p>${engineSource('config')} · ${engineSource('groot')}</p></details><details class="engine-details"><summary>Vì sao chưa gộp mọi model / World Model vào một head?</summary><p>FluxVLA có nhiều families và paths được cấu hình riêng. Model trong khảo sát có thể là policy thay thế, video generator, future-alignment objective hoặc world-action model. Chúng khác tokenizer, losses, temporal packing, memory và inference; cùng registry chưa đủ để hoán đổi modules bất kỳ.</p><p>FOCA-style action-free loss và common-wrist shared trunk là extensions cần xây/kiểm. DreamGen có thể tạo video offline; video không tự có robot actions. Xem recipes và bằng chứng ở trang khảo sát.</p><a href="#research">So cách training của các model →</a></details></section>
 <section class="engine-section">${engineTitle('04','Chạy trên robot thật cần gì?','Đây là lý do chọn engine: giữ model/preprocessing, tích hợp lớp hardware và timing đúng robot.')}<div class="engine-deploy-map"><article><small>LOCAL</small><h3>Máy robot chạy policy</h3><p>Sensor → online transforms → model → denormalize → chunk scheduler → operator / SDK</p></article><article><small>REMOTE GPU</small><h3>Robot gửi obs, server trả action</h3><p>Client sensor → ZMQ → server preprocess / predict / denormalize → client scheduler / operator</p></article></div><div class="engine-runtime-grid">${d.runtime.map(x=>`<article><span>${esc(x.tag)}</span><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p></article>`).join('')}</div><details class="engine-details engine-paper-detail"><summary>Xem architecture tăng tốc inference · Figure 5 gốc</summary>${enginePaperFigure('fluxInferenceAcceleration')}</details><details class="engine-details"><summary>Ví dụ upstream cụ thể: Franka / UR / Aloha và các humanoid operators</summary><p>Franka docs có π0.5 single/dual-arm, joint và Cartesian configs; runner/operator/action dimensions phải khớp. Remote serving docs mô tả URInferenceRunner và AlohaInferenceRunner; RTC docs có GR00T–Aloha path. Repo còn có Oli/Tron2 runner/operator paths.</p><p><strong>Đích A1:</strong> RoboCasa GR1 29D với waist chưa là task một tay/torso cố định, và chưa là real-GR1 integration. Cần xác minh SDK/operator, camera/state clocks, action convention, controller, checkpoint/normalization và end-to-end timing trước triển khai.</p><p>${engineSource('franka')} · ${engineSource('remote')} · ${engineSource('rtc')} · ${engineSource('eval','Các runner paths')}</p></details><div class="engine-limit"><strong>Trạng thái của project</strong><p>Reference MuJoCo nhỏ đã chạy. FluxVLA / GR00T / GR1 A1 và robot thật chưa được tích hợp, training hoặc nghiệm thu. Trang này mô tả nguồn upstream và thiết kế tích hợp, không vận hành robot.</p></div></section>
 <section class="engine-section">${engineTitle('05','Kết nối engine với data flywheel','Chạy model tạo evidence; evidence giúp quyết định sửa integration hay học từ dữ liệu nào.')}<ol class="engine-flywheel">${d.flywheel.map(([t,b],i)=>`<li><span>0${i+1}</span><strong>${esc(t)}</strong><p>${esc(b)}</p></li>`).join('')}</ol><div class="engine-return">↺ Release mới + replay → candidate mới → cùng protocol → gain / no-gain</div><div class="engine-tabs" role="group" aria-label="Can thiệp sau khi robot gặp lỗi">${d.failures.map((x,i)=>`<button type="button" data-engine-failure="${esc(x.id)}" aria-pressed="${i===0}" aria-controls="engine-failure-view">${esc(x.label)}</button>`).join('')}</div><div id="engine-failure-view" class="engine-failure-view" aria-live="polite"></div><div class="engine-bridge-links"><a href="#architecture">Chi tiết Data Core →</a><a href="#validation">Protocol kiểm chứng →</a></div><details class="engine-details"><summary>FluxVLA có sẵn gì, đội cần xây gì?</summary>${table(['Ranh giới','Kế thừa từ engine','Đóng góp / tích hợp của đội'],d.ownership.map(row=>row.map(esc)))}<p class="engine-note">Giá trị đề xuất: đưa engine và dữ liệu vào một vòng quyết định có bằng chứng. Framework hỗ trợ lifecycle không tự chứng minh source utility, few-shot gain hay tiết kiệm chi phí ở task A1.</p></details></section>
 <section class="engine-section engine-source-section">${engineTitle('06','Nguồn để kiểm lại','Đối chiếu riêng framework, selected policy và phần đội đề xuất.')}<div class="engine-source-grid">${d.sources.map(x=>`<article>${engineSource(x.id)}<p>${esc(x.scope)}</p></article>`).join('')}</div><details class="engine-details"><summary>Hồ sơ kỹ thuật đầy đủ và phạm vi kiểm nguồn</summary><p>${esc(d.sourceScope)}</p><p>Trước native run: khóa code commit, dependency versions, checkpoint/data revisions, config digest, processor và action profile. Việc đọc nguồn không thay thực nghiệm reproduction.</p><a href="#resources" data-document="${DOSSIER.findIndex(x=>x.path===ENGINEERING_DIR+'17-model-engine-core-fluxvla.md')}">Đọc hồ sơ Model Engine Core trong website →</a></details></section></div>`;}
function initModelEngineCore(signal){const root=document.querySelector('#model-engine-core');if(!root)return;const d=MODEL_ENGINE_CORE;
 root.querySelectorAll('img[src^="https:"]').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;},{signal}));
 function select(attr,id){root.querySelectorAll(`[${attr}]`).forEach(b=>b.setAttribute('aria-pressed',String(b.getAttribute(attr)===id)));}
 function failure(id){const x=d.failures.find(x=>x.id===id);root.querySelector('#engine-failure-view').innerHTML=`<div><small>QUAN SÁT</small><h3>${esc(x.label)}</h3><p>${esc(x.observed)}</p><strong class="engine-update-scope">${esc(x.scope)}</strong></div><div>${[['Kiểm / can thiệp',x.action],['Data cần giữ / lấy thêm',x.data],['Đo vòng sau',x.eval]].map(([t,b])=>`<article><small>${esc(t)}</small><p>${esc(b)}</p></article>`).join('')}</div>`;select('data-engine-failure',id);}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!root.contains(b))return;if(b.hasAttribute('data-engine-figure'))openDiagramDialog(b.closest('.engine-paper-figure'),b);if(b.dataset.engineJump){root.querySelector('#'+b.dataset.engineJump).scrollIntoView({behavior:'smooth',block:'start'});}if(b.dataset.engineModule){root.querySelector('#engine-module-view').innerHTML=engineModuleView(d.modules.find(x=>x.id===b.dataset.engineModule));select('data-engine-module',b.dataset.engineModule);}if(b.dataset.engineLife){root.querySelector('#engine-life-view').innerHTML=engineLifecycleView(d.lifecycle.find(x=>x.id===b.dataset.engineLife));select('data-engine-life',b.dataset.engineLife);}if(b.dataset.engineFailure)failure(b.dataset.engineFailure);},{signal});failure('binding');
}
